// Independently written, paragraph-cited essays. References were checked on 2026-10-26.
// No quotations or historical media are reproduced here.
const reviewedAt = '2026-10-26';
const p = (text, ...sourceIds) => ({ text, sourceIds });
const s = (id, title, ...paragraphs) => ({ id, title, paragraphs });
const t = (date, text, ...sourceIds) => ({ date, text, sourceIds });
const essay = (sections, timeline, sourceNote) => ({ reviewedAt, sections, timeline, sourceNote });

export const middleEssays = {
  'plessy-ferguson': essay([
    s('a-planned-challenge', 'A planned challenge from New Orleans', p('Homer Plessy was an Afro-Creole New Orleanian, a shoemaker, and a participant in an organized campaign for civil rights. The Citizens’ Committee formed in 1891 to challenge Louisiana’s Separate Car Act. Its members understood a segregated railway carriage as a restriction on citizenship, not simply a question of where a passenger sat. They arranged a test with the cooperation of the East Louisiana Railroad, which also objected to the requirements imposed on its business.', 'plessy-person')),
    s('making-a-case', 'Turning an arrest into a constitutional case', p('On June 7, 1892, Plessy bought passage to Covington and occupied a seat reserved for white passengers. The conductor’s challenge and a private detective’s arrest were arranged in advance. The journey stayed within Louisiana, allowing the committee to test the state’s power over travel inside its borders. Plessy’s refusal brought the law into court, where attorney Albion Tourgée challenged it. Judge John H. Ferguson rejected the challenge, and appeals eventually carried the dispute to the Supreme Court.', 'plessy-person', 'plessy')),
    s('majority-and-dissent', 'What the Court permitted', p('On May 18, 1896, the Court upheld Louisiana’s racial separation of railway passengers. The majority treated mandated separation as compatible with constitutional equality and dismissed the claim that the law itself imposed inferior status. Justice John Marshall Harlan dissented, identifying compulsory racial separation as an assault on citizens’ personal liberty. The disagreement concerned the meaning of emancipation and equal protection: whether states could keep using race to assign different places in public life after the Reconstruction amendments.', 'plessy')),
    s('a-long-legal-afterlife', 'A precedent challenged over generations', p('Plessy supplied constitutional protection for segregation long after the original train journey. Its eventual rejection in public education came through Brown v. Board of Education in 1954. Brown’s unanimous opinion held that dividing public schoolchildren by race denied equal protection even if buildings and other measurable resources appeared comparable. That reasoning attacked the separation itself. It did not mean that a new judicial opinion instantly integrated schools; implementation and resistance produced further legal and political struggles.', 'brown')),
  ], [
    t('1891', 'The Citizens’ Committee organizes to test Louisiana’s segregation law.', 'plessy-person'),
    t('June 7, 1892', 'Plessy is arrested during the planned railway challenge.', 'plessy-person'),
    t('May 18, 1896', 'The Supreme Court upholds the law, with Harlan dissenting.', 'plessy'),
  ], p('The court records establish what the judges decided; they do not validate the racial assumptions in the majority opinion. The National Park Service account restores the community organization behind a case often remembered only through its title.', 'plessy', 'plessy-person')),

  'naacp-founded': essay([
    s('violence-and-a-public-call', 'A response to violence and exclusion', p('The white attacks on Black residents of Springfield, Illinois, in 1908 helped prompt the campaign that became the NAACP. Organizers placed this violence alongside lynching, disenfranchisement, and segregation elsewhere. A public call issued on February 12, 1909, deliberately used the centenary of Abraham Lincoln’s birth to measure the distance between emancipation and actual citizenship. Its signers included Black reformers W. E. B. Du Bois, Ida B. Wells-Barnett, and Mary Church Terrell alongside white supporters.', 'naacp')),
    s('founding-was-a-process', 'From a conference to a permanent association', p('The familiar founding date marks the call, rather than a fully formed national organization appearing in one day. A National Negro Conference met in New York on May 31 and June 1, 1909. Participants created a committee to plan a continuing body. At a subsequent meeting on May 12, 1910, that committee adopted the name National Association for the Advancement of Colored People. The sequence matters because the association grew through discussion, recruitment, and decisions about how a multiracial organization would work.', 'naacp-founding-loc')),
    s('organizing-and-publicity', 'Building a voice and a membership', p('The Crisis began in November 1910 under Du Bois’s editorship. It carried reports of the association’s work alongside political argument, fiction, poetry, visual art, and accounts of Black achievement. This editorial range joined the defense of civil rights to a broader public conversation about Black life. The magazine could reach readers who were far from the national office, making publishing one of the association’s organizing tools and giving its campaigns a recurring public platform.', 'naacp-founding-loc')),
    s('methods-and-tensions', 'An organization with several tools', p('The association pursued litigation, local branches, protest, and pressure for legislation. Its anti-lynching campaign combined documentation with public mobilization and efforts to secure a federal law. Its multiracial character did not mean equal representation in early leadership: Du Bois was the only Black member among its original executives. Reading that imbalance alongside the association’s growth helps explain why its history involves arguments over leadership and methods as well as campaigns against discrimination outside the organization.', 'naacp')),
  ], [
    t('February 12, 1909', 'The public call establishes the association’s commemorative founding date.', 'naacp'),
    t('May 31–June 1, 1909', 'The National Negro Conference meets in New York.', 'naacp-founding-loc'),
    t('November 1910', 'The first issue of The Crisis appears.', 'naacp-founding-loc'),
  ], p('The NAACP’s account describes its own institutional development. The Library of Congress exhibition places surviving calls, platforms, and publications beside that narrative and distinguishes the 1909 organizing effort from the adoption of the name in 1910.', 'naacp-founding-loc')),

  'great-migration': essay([
    s('many-decisions-to-leave', 'Millions of decisions about freedom', p('Between roughly 1910 and 1970, about six million Black people left the South for Northern, Midwestern, and Western states. The dates mark a broad demographic transformation, not the beginning and end of every family’s journey. People sought work and schooling, but also distance from racial terror and the restrictions of Jim Crow. Describing the migration only as a response to factory wages would miss those demands for safety and greater control over everyday life.', 'migration')),
    s('how-information-traveled', 'The networks that made departure possible', p('Information moved through relatives, friends, newspapers, and labor recruiters. The Chicago Defender advertised employment and the possibilities of Northern cities; people who had already moved sent news back to those considering departure. Rail connections shaped where travelers could go. Boston, for example, received migrants traveling up the East Coast through other major cities. Such connections made migration a collective process even when individuals traveled separately: earlier migrants helped later arrivals imagine a destination and find a place within it.', 'migration-boston')),
    s('war-work-and-new-destinations', 'Two broad waves, changing opportunities', p('World War I increased industrial demand while military service and reduced immigration constrained the labor supply. A later surge accompanied World War II’s defense expansion and extended migration farther west, including California and the Pacific Northwest. Employment opportunities changed from place to place. In Boston, the Charlestown Navy Yard’s wartime production drew Black workers, including people with Southern connections. The national movement therefore joined many local labor markets; no single city or occupation can stand for all its participants.', 'migration', 'migration-boston')),
    s('arrival-and-its-limits', 'Building a life after arrival', p('Relocation did not end racism. Housing discrimination, restrictive covenants, and redlining helped segregate destination cities. At the same time, established Black neighborhoods and institutions offered practical assistance. In Boston’s Roxbury neighborhood, churches and community groups helped newcomers settle; the local NAACP and Urban League also supported employment searches. Read together, these experiences show why arrival was the beginning of another struggle: families pursued opportunity while building support within cities that continued to limit where they could live and work.', 'migration', 'migration-boston')),
  ], [
    t('c. 1910–1940', 'The first broad phase draws migrants especially to Northern and Midwestern cities.', 'migration'),
    t('World War II', 'Defense production creates new destinations and employment opportunities.', 'migration'),
    t('November 1943', 'A Navy Yard report records more than 2,000 Black civilian workers in Boston.', 'migration-boston'),
  ], p('The six-million figure is an estimate covering decades. The Boston study also notes gaps in employment records: categories that combine minority workers can conceal migrants’ origins. A national count cannot substitute for individual family histories.', 'migration', 'migration-boston')),

  'harlem-renaissance': essay([
    s('new-urban-cultural-worlds', 'Culture in a changing urban world', p('The Harlem Renaissance developed as migration transformed Black urban life. Harlem became an influential meeting place for writers, intellectuals, performers, and visual artists, while related activity flourished in other cities. Its boundaries cannot be reduced to a single opening night or publication. The Metropolitan Museum’s account follows work from the 1920s into the 1940s, illustrating how artistic careers and exchanges continued beyond the shorter period usually used to introduce the movement.', 'harlem-met')),
    s('locke-and-self-definition', 'Alain Locke and the demand for self-definition', p('In March 1925, philosopher Alain Locke edited a special Harlem issue of Survey Graphic; an anthology, The New Negro, followed that year. In his essay “Enter the New Negro,” Locke argued that Black people had too often been represented as problems for others to manage. He described a generation claiming the authority to represent its own experience. This was an intervention in a debate, rather than a neutral description of everyone’s views: Locke was proposing a cultural direction and inviting readers to recognize it.', 'harlem-locke')),
    s('more-than-one-art-form', 'Portraits, poetry, and everyday life', p('Poetry by writers including Langston Hughes and Claude McKay helped articulate pride and protest, while artists developed images of modern Black subjects. Aaron Douglas, Augusta Savage, James Van Der Zee, and Laura Wheeler Waring worked in different media and styles. Their presence in the same cultural history does not make their work interchangeable. Portraiture, photography, sculpture, and literature offered distinct ways to portray intellectual life, ordinary people, and the changing possibilities of self-presentation.', 'harlem-locke', 'harlem-met')),
    s('networks-beyond-harlem', 'A movement wider than one neighborhood', p('Locke’s framing drew attention to African, Caribbean, and American cultural connections. The Met’s exhibition likewise places Black American artists within international modern art and transatlantic exchange. These perspectives broaden the familiar neighborhood label without making Harlem unimportant. They also direct attention to the institutions that preserved the work: historically Black colleges and universities supplied a substantial portion of the exhibition’s loans. The movement’s later visibility depends partly on those collections and the sustained work of keeping art available for study.', 'harlem-locke', 'harlem-met')),
  ], [
    t('1920s', 'Harlem becomes a major center of Black cultural and intellectual activity.', 'harlem-locke'),
    t('March 1925', 'Locke publishes “Enter the New Negro” in Survey Graphic.', 'harlem-locke'),
    t('1934', 'Aaron Douglas creates Aspects of Negro Life: From Slavery through Reconstruction.', 'harlem-met'),
  ], p('Locke’s essay is a participant’s argument about cultural change. The Met offers a later interpretation centered on visual art. These are complementary perspectives, not a claim that every artist shared a single program or that the movement ended at one agreed date.', 'harlem-locke', 'harlem-met')),

  'tulsa-massacre': essay([
    s('greenwood-before-the-attack', 'Greenwood before the destruction', p('Greenwood was a Black residential and commercial district in Tulsa, with businesses, churches, and other community institutions. Its prosperity helped produce the name Black Wall Street, but the district was also a place of homes and ordinary daily life. On May 30, 1921, an encounter involving Dick Rowland and Sarah Page in a downtown elevator became the subject of rumors. The details remain disputed. Rowland’s arrest the next day and inflammatory newspaper coverage helped create the immediate crisis.', 'tulsa-museum')),
    s('racial-violence-and-official-power', 'The attack and the failure of protection', p('Black residents feared Rowland would be lynched. Armed groups gathered at the courthouse; after gunfire, Black defenders retreated toward Greenwood. White attackers subsequently looted and burned the district. The museum’s presentation of the state commission’s findings emphasizes official responsibility: authorities armed and deputized white men, including participants in the violence, while National Guard units detained Black residents. This was not simply an unexplained clash between equivalent groups. The destruction occurred alongside the failure, and in some cases participation, of public authorities.', 'tulsa-museum')),
    s('losses-and-uncertain-counts', 'What can be counted, and what cannot', p('By June 1, much of Greenwood lay destroyed. Oklahoma’s state archival collection describes devastation across thirty-five square blocks and identifies the death toll as unconfirmed. The Smithsonian’s collection guide records the destruction of more than a thousand homes, businesses, and churches, and the murder of scores of Black residents. Those accounts support the scale of the catastrophe without establishing an exact number of people killed. A precise-looking total would conceal the limits of the surviving record.', 'tulsa-state', 'tulsa')),
    s('survivors-and-the-record', 'Survivors keep the history in view', p('The Smithsonian preserves interviews made in 2004–2007 with survivors, descendants, witnesses, historians, and community supporters. The collection also documents efforts to obtain acknowledgment and restitution. Its importance extends beyond confirming a sequence of attacks: it records how people described the losses and carried their knowledge across generations. Because the collection is an edited selection from a larger project, readers should distinguish its archival description from a complete inventory of every testimony or every experience of the massacre.', 'tulsa')),
  ], [
    t('May 31, 1921', 'Rowland’s arrest and a courthouse confrontation precede the wider assault.', 'tulsa-museum'),
    t('June 1, 1921', 'White attackers burn and devastate Greenwood.', 'tulsa-state'),
    t('2004–2007', 'Interviews document survivors, descendants, and the struggle for acknowledgment.', 'tulsa'),
  ], p('This account uses massacre to identify the devastating attack on Greenwood. Older archival titles sometimes use riot. The state collection explicitly leaves the death toll unresolved; the Smithsonian guide describes oral histories rather than independently verifying each statement within them.', 'tulsa-state', 'tulsa')),

  'negro-history-week': essay([
    s('education-and-exclusion', 'The problem Woodson set out to change', p('Carter G. Woodson understood that the absence of Black history from teaching shaped what Americans believed about the country. Born to formerly enslaved parents, he worked in West Virginia coalfields before completing high school and continuing his education. He earned a Harvard doctorate in history in 1912. His career joined formal scholarship to experiences far outside elite universities, including the stories of Black workers whose lives rarely appeared in the historical accounts available to students.', 'woodson-bio', 'woodson-mines')),
    s('institutions-before-an-observance', 'Research needed an institutional home', p('In 1915, Woodson helped establish the Association for the Study of Negro Life and History. He also developed scholarly publishing and the Journal of Negro History, building places where research could circulate despite exclusion by established institutions. His Washington office-home later brought several parts of that work together: the association, Associated Publishers, publications, correspondence, and collections of historical documents. The public observance of history rested on this continuing labor of finding, preserving, editing, and distributing evidence.', 'woodson-mines', 'woodson-home')),
    s('the-week-in-february', 'A week intended to widen historical knowledge', p('Woodson launched Negro History Week in February 1926. Its timing connected with commemorations of Abraham Lincoln and Frederick Douglass, giving educators and communities a recognizable point around which to organize. The purpose extended beyond listing famous names. Woodson wanted Black experience placed within the history of the world and the United States, challenging the prejudices built into what schools omitted. The week supplied a recurring occasion for that work; it did not exhaust the association’s scholarly or educational mission.', 'woodson-mines')),
    s('the-work-behind-public-history', 'The everyday labor of a historical movement', p('Woodson’s office-home also served as a place of mentoring for younger historians. Its activities included answering correspondence, preparing manuscripts, mailing books, maintaining a library, and preserving archival material. Langston Hughes worked there during the 1920s. These details make the observance more concrete: a public campaign depended on administrative and intellectual work performed throughout the year. After Woodson’s death in 1950, the association and publishing operation continued using the house, showing how the institutions outlasted their founder.', 'woodson-home')),
  ], [
    t('1912', 'Woodson earns his doctorate in history at Harvard.', 'woodson-bio'),
    t('September 9, 1915', 'He helps establish the historical association.', 'woodson-bio'),
    t('February 1926', 'Negro History Week begins.', 'woodson-mines'),
  ], p('The National Park Service biographies and office-home history connect the observance to research and publishing. They should not be read as suggesting that Black historical thought began with Woodson; the focus here is the particular institutions and annual observance he helped build.', 'woodson-bio', 'woodson-home')),
  'anderson-lincoln-memorial': essay([
    s('an-established-artist-excluded', 'An acclaimed artist denied a stage', p('Marian Anderson’s 1939 concert controversy concerned an internationally successful contralto. She had toured Europe, performed at Carnegie Hall, and attracted enthusiastic audiences in the United States. Yet professional acclaim did not remove racial barriers. Washington’s Constitution Hall, owned by the Daughters of the American Revolution, barred Black performers. When organizers sought a large venue for Anderson’s Howard University-sponsored concert, that rule prevented her from appearing there. The exclusion exposed how a cultural institution could deny opportunity even to a celebrated artist.', 'anderson-roosevelt')),
    s('a-coalition-finds-a-venue', 'Organizing an answer to exclusion', p('Walter White of the NAACP worked to mobilize support and find another venue. Eleanor Roosevelt’s resignation from the DAR brought further public attention to the dispute. Interior Secretary Harold Ickes helped make the Lincoln Memorial available for an outdoor performance. Their roles were connected but distinct: civil rights organizing, public pressure, and federal access to the site all mattered. The resulting concert was possible because Anderson and her supporters transformed a rejected booking into a much larger public event.', 'anderson', 'anderson-loc')),
    s('the-easter-performance', 'Easter Sunday at the Lincoln Memorial', p('On April 9, 1939, Anderson sang before an integrated crowd estimated at about 75,000. Radio carried the performance to listeners beyond Washington. Her program included patriotic music and spirituals, placing a Black artist’s voice at a monument associated with emancipation and national citizenship. The meaning of the gathering came from both the performance and its circumstances: the audience assembled outdoors because an indoor cultural institution had refused to let the singer use its stage.', 'anderson-loc')),
    s('change-and-continuing-barriers', 'What the concert changed', p('The concert made Anderson’s exclusion a national civil rights issue and demonstrated the reach of a coalition organized around cultural access. It also belongs within a longer career, not solely within a story about the first lady. Anderson returned to Constitution Hall in 1943 for a benefit concert. The sequence of refusal, public performance, and later admission shows change at a particular institution; it does not establish that the Easter concert ended segregation across American musical life.', 'anderson', 'anderson-loc')),
  ], [
    t('1939', 'The DAR refuses Constitution Hall for Anderson’s concert.', 'anderson'),
    t('April 9, 1939', 'Anderson performs at the Lincoln Memorial before an integrated audience.', 'anderson-loc'),
    t('1943', 'She appears at Constitution Hall for a benefit concert.', 'anderson-loc'),
  ], p('The crowd figure is an estimate. Institutional histories describe different contributors to the event; keeping Anderson’s established career and the NAACP’s organizing in view avoids reducing the concert to a story about a single powerful supporter.', 'anderson-roosevelt', 'anderson')),

  'executive-order-8802': essay([
    s('defense-jobs-and-exclusion', 'A defense buildup that excluded workers', p('As the United States expanded defense production in 1941, Black workers faced exclusion from jobs supported by federal spending. A. Philip Randolph, leader of the Brotherhood of Sleeping Car Porters, pressed the contradiction between national defense and discrimination at home. He worked with other civil rights leaders, including NAACP secretary Walter White, to demand action. Their campaign treated employment as a question of citizenship and government responsibility, rather than leaving access to defense work entirely to individual employers.', 'wartime-rights-loc')),
    s('the-threat-of-a-march', 'Negotiation backed by mass protest', p('Randolph proposed bringing a large demonstration to Washington. The threat gave negotiations with the Roosevelt administration urgency. Randolph and White met with the president and other officials on June 18, 1941; Roosevelt issued Executive Order 8802 a week later. The march was then called off. This sequence shows a form of collective pressure that produced a federal response before the planned demonstration took place. The order was a concession won through organizing, not simply a policy announced without a campaign behind it.', 'wartime-rights-loc', 'order-8802')),
    s('what-the-order-required', 'Contracts, training, and complaints', p('The order prohibited discrimination in defense employment and government on grounds of race, creed, color, or national origin. It directed agencies responsible for defense training to administer those programs without discrimination and required future defense contracts to contain nondiscrimination provisions. A Committee on Fair Employment Practice could receive and investigate complaints, seek remedies, and recommend further measures. Those provisions linked the government’s purchasing power to access to work, giving workers a federal channel through which to challenge exclusion.', 'order-8802')),
    s('scope-and-unfinished-demands', 'A limited victory with a longer history', p('The order addressed employment; it did not integrate the armed forces. That distinction matters because Randolph’s campaign had challenged discrimination in both defense industries and military service. In 1948, Harry Truman issued a separate order establishing equality of treatment and opportunity in the armed services. The years between the two orders make clear that one executive action did not resolve the entire struggle. Wartime pressure opened an avenue for federal intervention while leaving other institutions and enforcement problems to later campaigns.', 'wartime-rights-loc', 'order-9981')),
  ], [
    t('March 18, 1941', 'Randolph writes White proposing a mass march against discrimination.', 'wartime-rights-loc'),
    t('June 18, 1941', 'Randolph and White meet Roosevelt at the White House.', 'wartime-rights-loc'),
    t('June 25, 1941', 'Roosevelt signs Executive Order 8802.', 'order-8802'),
  ], p('The order documents federal policy and the committee’s assigned powers. It does not, by itself, show that employers complied. The Library of Congress places the directive beside organizing correspondence, helping distinguish the text of reform from the pressure that produced it.', 'order-8802', 'wartime-rights-loc')),

  'jackie-robinson-debut': essay([
    s('the-road-to-brooklyn', 'The road from the Monarchs to Brooklyn', p('Jackie Robinson’s Dodgers debut followed experience in the Army, the Negro Leagues, and minor league baseball. After military service, he joined the Kansas City Monarchs in 1945. Branch Rickey signed him to the Dodgers’ organization that October, and Robinson played for the Montreal Royals in 1946 before moving to Brooklyn. That path matters: the 1947 milestone opened a previously segregated professional institution to a player whose abilities had already developed in other demanding settings.', 'robinson-life')),
    s('opening-day-at-ebbets-field', 'April 15 at Ebbets Field', p('Robinson played first base for the Brooklyn Dodgers against the Boston Braves on April 15, 1947. Sportswriter Tom Meany recorded the game in a scorebook now held by the National Baseball Hall of Fame and Museum. A ground ball produced Robinson’s first defensive putout, and a later bunt helped him reach base and score. Brooklyn won 5–3. The surviving record gives the occasion ordinary baseball detail alongside its extraordinary place in the history of racial exclusion.', 'robinson')),
    s('the-meaning-of-the-barrier', 'What this debut did, and did not, mean', p('The milestone concerns the twentieth-century color barrier in the American and National Leagues. Black professional baseball already existed, including the Monarchs team for which Robinson had played. Calling him the first Black professional player would erase that history. His debut instead changed access to the Dodgers and the major-league system from which Black players had been excluded. The archival record can therefore tell two connected stories: a specific athlete’s performance and an institution beginning to abandon its racial boundary.', 'robinson', 'robinson-life')),
    s('beyond-a-first-game', 'A public life beyond the diamond', p('Robinson’s later life extended the struggle for opportunity beyond baseball. He raised money for the NAACP, spoke publicly about civil rights, and pursued business projects intended to expand Black economic opportunity. His papers include correspondence, speeches, contracts, and other material documenting those activities. Reading that record prevents the opening-day milestone from freezing him permanently in the role of a silent symbol. The player who entered Ebbets Field also became an outspoken participant in debates over equality and public life.', 'robinson-life', 'robinson-papers')),
  ], [
    t('1945', 'Robinson plays for the Kansas City Monarchs and signs with the Dodgers’ organization.', 'robinson-life'),
    t('1946', 'He plays for the Montreal Royals.', 'robinson-life'),
    t('April 15, 1947', 'He debuts for Brooklyn at Ebbets Field.', 'robinson'),
  ], p('Meany’s scorebook is evidence of the game, interpreted here through the Hall of Fame’s collection account. Robinson’s papers document a much wider career. Neither source makes one debut equivalent to the immediate integration of every club or of the sport’s leadership.', 'robinson', 'robinson-papers')),

  'executive-order-9981': essay([
    s('service-with-unequal-opportunity', 'Military service under unequal conditions', p('Black Americans served the country while military segregation restricted assignments, advancement, and recognition. The Truman Library’s historical materials place the 1948 directive against that contradiction between service and unequal treatment. The decision also should not be read as proof that the president had always opposed racism. The library explicitly discusses his personal prejudices alongside his official action, making the distinction between a public policy decision and a simple story of an unchanging personal commitment.', 'truman-rights')),
    s('the-presidential-directive', 'The policy announced on July 26', p('Executive Order 9981 established equality of treatment and opportunity for members of the armed services regardless of race, color, religion, or national origin. Truman signed it on July 26, 1948. Its wording directed implementation as rapidly as possible while taking account of changes affecting efficiency and morale. The order therefore supplied a binding presidential policy and a process for applying it, rather than a statement that every unit and assignment had already become integrated on the date of signing.', 'order-9981')),
    s('changing-military-practice', 'The machinery of implementation', p('A presidential committee was authorized to examine the services’ rules, procedures, and practices and recommend changes. Federal agencies had to cooperate and supply information. Chaired by Charles Fahy, the committee submitted its final report in May 1950. Military resistance remained substantial, and desegregation developed through implementation over the following years. The National Archives places the near-completion of military integration by the end of the Korean conflict, emphasizing the distance between issuing an order and changing an institution.', 'order-9981')),
    s('reading-the-political-setting', 'A decision made amid competing pressures', p('The Truman Library brings together public addresses, correspondence, polling, and political advice for examining why the administration acted. Its teaching collection includes the president’s June 1947 NAACP address, a February 1948 message to Congress, and letters from citizens and civil rights advocates. Those materials make it possible to investigate moral arguments, political calculation, and demands from outside the White House together. They caution against attributing a major policy shift either to presidential goodwill alone or to a single private motive.', 'truman-rights')),
  ], [
    t('June 29, 1947', 'Truman addresses the NAACP.', 'truman-rights'),
    t('July 26, 1948', 'Executive Order 9981 establishes the equality policy.', 'order-9981'),
    t('May 22, 1950', 'The Fahy committee submits its final report.', 'order-9981'),
  ], p('The executive order is the primary evidence for the policy’s language and machinery. Later institutional accounts describe implementation. The presidential library’s source collection poses questions about motivation; it does not establish that one explanation accounts for the entire decision.', 'truman-rights')),

  'brown-board': essay([
    s('families-and-local-campaigns', 'Families made a national case possible', p('Brown grew from local campaigns in which parents and students challenged educational segregation. In Topeka, thirteen parents sought access for their children to white schools. In South Carolina, a dispute over school transportation developed into a challenge to segregation itself. A student strike in Farmville, Virginia, likewise became litigation. These histories place the plaintiffs’ organizing before the famous Supreme Court announcement: families took risks and built cases that lawyers could carry into federal court.', 'brown-five-cases')),
    s('related-cases-distinct-grounds', 'One constitutional problem, several legal paths', p('The Brown opinion considered school cases from Kansas, South Carolina, Virginia, and Delaware. Their circumstances differed, but they raised the common question of whether state-imposed segregation denied equal protection under the Fourteenth Amendment. The accompanying Washington, D.C., case, Bolling v. Sharpe, concerned a federal district rather than a state. Keeping these cases visible prevents the familiar Topeka name from obscuring the students, parents, and communities who pursued related challenges across several jurisdictions.', 'brown', 'brown-five-cases')),
    s('the-holding', 'Separation itself violated equal protection', p('On May 17, 1954, Chief Justice Earl Warren delivered a unanimous decision. The Court held that segregating public schoolchildren by race violated equal protection even where physical facilities and other measurable resources were comparable. Its reasoning therefore went beyond ordering equal buildings or equipment. Racial separation itself denied equal educational opportunity. The ruling rejected the application of Plessy’s separate-but-equal doctrine to public education and gave plaintiffs a constitutional basis for demanding access to schools without state-enforced racial division.', 'brown')),
    s('enforcement-after-the-opinion', 'A judgment still had to be enforced', p('The Court separated the constitutional ruling from the question of implementation. On May 31, 1955, Brown II directed states to begin desegregation plans, but supplied no firm completion deadline. Its open-ended language left families facing resistance after they had won the underlying right.', 'brown'), p('The conflict did not end with the announcement. In Little Rock in 1957, a plan to desegregate Central High met obstruction by the governor and hostility from white crowds. President Dwight Eisenhower ultimately sent federal troops to protect the students and uphold the court orders. That episode shows why the meaning of Brown includes both a legal holding and the struggle to make it effective. A right recognized in Washington still depended on enforcement where children actually attended school.', 'little-rock-presidential')),
  ], [
    t('1951', 'The Farmville student strike helps generate the Virginia school-segregation case.', 'brown-five-cases'),
    t('May 17, 1954', 'The Supreme Court announces its unanimous Brown decision.', 'brown'),
    t('May 31, 1955', 'Brown II addresses how school desegregation should proceed.', 'brown'),
    t('September 1957', 'The Little Rock crisis tests enforcement of school desegregation.', 'little-rock-presidential'),
  ], p('The court opinion establishes the legal holding; the National Park Service traces the local cases behind it. The five-case grouping commonly includes Bolling, but Brown’s own opinion addresses the state cases. The distinction preserves the different constitutional setting of Washington, D.C.', 'brown', 'brown-five-cases')),

  'emmett-till': essay([
    s('a-family-visit', 'A child visiting relatives', p('Emmett Till was fourteen when he traveled from Chicago to visit relatives in the Mississippi Delta in August 1955. His family’s connections joined two places shaped by the Great Migration: a Northern home and relatives remaining in the South. Accounts of his interaction with Carolyn Bryant at a store in Money differ. What followed is clear: white men abducted him from his relatives’ home on August 28 and murdered him. His body was recovered from the Tallahatchie River three days later.', 'till', 'till-doj')),
    s('mamie-till-mobleys-decision', 'A mother makes the crime visible', p('Mamie Till-Mobley insisted that her son’s body be returned to Chicago and chose an open-casket funeral. Services began at Roberts Temple Church of God in Christ on September 3. Her decision confronted mourners and a wider public with the reality of racial violence. The church, family networks, and funeral arrangements are essential parts of the history: the public response did not occur automatically when the murder happened. It depended on a mother’s insistence that the harm be seen and remembered.', 'till')),
    s('trial-and-impunity', 'An acquittal despite the crime', p('Mississippi authorities tried Roy Bryant and J. W. Milam before an all-white jury, which acquitted them. The men later admitted the killing to a journalist. Federal investigators did not conduct a murder investigation in 1955; the Justice Department’s later account explains the limitations of federal criminal civil rights jurisdiction at that time. The distinction is important. The failure to obtain a conviction was not evidence that no crime had occurred, and later admissions did not erase the consequences of the original acquittal.', 'till-doj')),
    s('later-investigations-and-memory', 'Evidence, investigation, and remembrance', p('Decades later, federal investigators reopened the case and worked with Mississippi authorities. The FBI’s account describes interviews, documentary research, and forensic work, while identifying legal obstacles to federal prosecution. These investigations belong to the continuing effort to establish responsibility and confront the earlier failure of justice. They also reveal why historical knowledge and a prosecutable criminal case are different things: surviving evidence may illuminate an event even when the legal conditions for bringing charges cannot be met.', 'till-fbi')),
  ], [
    t('August 28, 1955', 'Till is abducted and murdered in Mississippi.', 'till-doj'),
    t('September 3, 1955', 'Funeral services begin at Roberts Temple in Chicago.', 'till'),
    t('2004', 'A federal investigation reopens the case decades after the killing.', 'till-doj'),
  ], p('The 2023 monument proclamation is a commemorative account; the Justice Department’s closing memorandum explains investigative findings and legal limits. The disputed store encounter is not treated as settled fact, and uncertainty about it does not diminish responsibility for the abduction and murder.', 'till-doj')),
  'montgomery-boycott': essay([
    s('women-organize-before-parks', 'Organizing before the arrest', p('Montgomery’s bus protest grew from years of work by local residents. The Women’s Political Council challenged humiliating practices such as requiring Black riders to pay at the front and then enter at the rear. Jo Ann Robinson warned city officials in May 1954 that a boycott was under discussion. When Rosa Parks was arrested on December 1, 1955, the council had both a grievance and a network ready to act. Members prepared and distributed leaflets calling for a one-day boycott.', 'boycott-wpc')),
    s('a-day-becomes-a-campaign', 'Building an organization that could last', p('The December 5 protest succeeded strongly enough for residents to continue. Local leaders formed the Montgomery Improvement Association and elected Martin Luther King Jr. its president. The association’s initial demands included courteous treatment, a revised seating arrangement, and Black drivers on predominantly Black routes. After officials penalized Black taxi drivers who assisted protesters, the association organized a carpool of about 300 cars. T. J. Jemison shared experience from the 1953 Baton Rouge boycott. Transport, fundraising, and volunteer work enabled residents to keep reaching their jobs while withholding bus fares.', 'boycott')),
    s('pressure-on-the-protesters', 'The cost of keeping the boycott going', p('City officials and white opponents tried to break the protest through legal action, harassment, and violence. Bombings struck the homes of King and E. D. Nixon. Authorities prosecuted boycott leaders and attacked the carpool system. Women continued organizing meetings, driving, and maintaining the daily networks. Their labor is easy to miss in accounts centered on ministers, but it explains how a campaign endured for more than a year. Participation meant repeated decisions under pressure, not one symbolic refusal to ride.', 'boycott', 'boycott-wpc')),
    s('the-women-in-browder', 'The separate lawsuit that ended legal segregation', p('Fred Gray and Charles Langford filed Browder v. Gayle in February 1956. Its plaintiffs included Aurelia Browder, Susie McDonald, Claudette Colvin, and Mary Louise Smith; Jeanatta Reese withdrew under pressure. Parks was not a plaintiff in this federal case. A district court ruled against bus segregation in June, and the Supreme Court affirmed in November. Organizers waited for the enforceable order to arrive before ending the boycott on December 20. Integrated bus service began the next day.', 'boycott-browder')),
  ], [
    t('May 21, 1954', 'Robinson warns the mayor that a boycott is being considered.', 'boycott-wpc'),
    t('December 5, 1955', 'The boycott begins and the Montgomery Improvement Association forms.', 'boycott'),
    t('December 20–21, 1956', 'The boycott ends; riders return to integrated buses.', 'boycott-browder'),
  ], p('The King Institute distinguishes mass protest from the Browder lawsuit. Keeping both histories visible avoids treating Parks’s arrest as the court case that directly struck down bus segregation or overlooking the women who organized and litigated.', 'boycott-browder', 'boycott-wpc')),

  'little-rock-nine': essay([
    s('students-choose-central', 'Students choose a school, and a difficult path', p('Little Rock’s gradual desegregation plan called for Black students to enter Central High in 1957. Volunteers faced restrictions on activities and pressure on their families. The nine who ultimately attended were Minnijean Brown, Elizabeth Eckford, Ernest Green, Thelma Mothershed, Melba Pattillo, Gloria Ray, Terrence Roberts, Jefferson Thomas, and Carlotta Walls. Their choices put teenagers at the center of a conflict over whether the constitutional rights recognized in Brown would govern the actual operation of a public school.', 'little-rock')),
    s('obstruction-and-federal-action', 'The struggle at the school entrance', p('Governor Orval Faubus used the Arkansas National Guard to prevent Black students from entering. Attorneys Thurgood Marshall and Wiley Branton obtained an injunction against that use of troops on September 20. A further attempt to attend school on September 23 met a violent crowd. President Eisenhower then federalized the Guard and sent soldiers from the 101st Airborne Division. On September 25, the Nine completed their first full school day under federal protection.', 'little-rock', 'little-rock-marshall', 'little-rock-presidential')),
    s('inside-the-building', 'Admission did not bring safety', p('Military escort did not eliminate abuse inside Central. Guards accompanied students between classes but could not remain with them everywhere. The Nine endured verbal and physical attacks; white classmates who offered friendship could also face threats. Minnijean Brown was expelled during the school year and completed her schooling elsewhere. Ernest Green graduated from Central in May 1958. These different outcomes resist a simple triumphant ending: access to the building did not give the students an equal or secure experience within it.', 'little-rock')),
    s('delay-and-the-lost-year', 'The fight continued after 1957', p('In 1958, the school board sought a thirty-month delay in desegregation. Marshall represented the families challenging that retreat in Cooper v. Aaron. The Supreme Court rejected the delay and affirmed the binding force of its constitutional decisions despite state resistance. Faubus nevertheless closed Little Rock’s public high schools, producing the period remembered as the Lost Year. The struggle therefore moved from exclusion at a school entrance to an attempt to halt public schooling itself rather than continue integration.', 'little-rock-marshall')),
  ], [
    t('September 20, 1957', 'A federal judge enjoins the governor’s use of troops to obstruct integration.', 'little-rock-marshall'),
    t('September 25, 1957', 'The Nine complete their first full day at Central under federal escort.', 'little-rock'),
    t('1958', 'Cooper v. Aaron rejects delay; the governor closes the city’s public high schools.', 'little-rock-marshall'),
  ], p('The National Park Service account includes students’ experiences as well as official action. Presidential records document the federal response, but that perspective alone cannot explain the sustained harassment or educational disruption experienced by the students and their families.', 'little-rock', 'little-rock-presidential')),

  'greensboro-sit-in': essay([
    s('four-students-take-seats', 'Four freshmen confront a segregated counter', p('On February 1, 1960, Ezell Blair Jr., Franklin McCain, Joseph McNeil, and David Richmond sat at the Woolworth lunch counter in Greensboro and requested service. The students attended North Carolina Agricultural and Technical College. Staff refused to serve them, but they stayed. Their action made an everyday commercial space a place of political confrontation: the store accepted Black customers’ purchases while reserving its lunch-counter seating for white people. Remaining seated challenged that contradiction in front of employees and customers.', 'greensboro', 'greensboro-uncg')),
    s('why-the-tactic-mattered', 'A small action designed to be repeated', p('The students had bought items elsewhere in the store and kept the receipts. After being denied food service, they could point to the money Woolworth had already accepted from them. The first day ended without service, but the protest did not depend on a single confrontation persuading management immediately. Returning and remaining at the counter put the store’s policy under continuing scrutiny. The university archive’s account makes clear that the action involved discussion and preparation, rather than four students merely stumbling into a dispute.', 'greensboro-uncg')),
    s('a-growing-student-campaign', 'More students, more cities', p('Additional students joined on subsequent days, including students from neighboring colleges. Organizers used shifts so participants could continue attending classes. Related protests spread through other North Carolina cities and into Virginia and Tennessee. Greensboro helped accelerate a wider student movement because its tactic was visible and repeatable: young people could confront exclusion in an ordinary place that exposed the terms of everyday segregation. The growing movement required local choices and organizing in each city, rather than a single national command.', 'greensboro-place')),
    s('months-of-local-pressure', 'Winning service took sustained pressure', p('The Greensboro campaign continued for months. Students were joined by churches, civil rights organizations, and other community members. The counter began serving Black customers on July 25, 1960. That interval is central to the story: the famous first afternoon opened a campaign whose result depended on sustained participation. The Smithsonian preserves a section of the counter as evidence of the struggle. The object points back to a network of people and actions, rather than containing the entire history in four seats.', 'greensboro')),
  ], [
    t('February 1, 1960', 'The four students begin the Woolworth sit-in.', 'greensboro'),
    t('February 1960', 'The protest grows and related sit-ins spread to other cities.', 'greensboro-place'),
    t('July 25, 1960', 'Woolworth’s Greensboro counter begins serving Black customers.', 'greensboro'),
  ], p('Museum and university accounts establish the first protest and the longer campaign. Daily crowd estimates differ between institutional summaries, so this essay emphasizes documented growth without presenting one exact daily attendance series as definitive.', 'greensboro', 'greensboro-place', 'greensboro-uncg')),

  'sncc-founded': essay([
    s('connecting-the-sit-ins', 'Connecting a movement of local protests', p('The sit-ins spreading across the South in early 1960 created a need for students to exchange strategies and maintain contact. Ella Baker, then working with the Southern Christian Leadership Conference, recognized that opportunity. She persuaded the organization to support a meeting at Shaw University, her alma mater, in Raleigh. The April gathering brought young activists together from different campaigns. It connected experiences already developed locally rather than creating student protest from nothing.', 'sncc-birth')),
    s('independence-at-shaw', 'Why an independent student organization mattered', p('Some SCLC leaders hoped the meeting would produce a student wing of their organization. Baker urged the participants to consider an independent body instead. The resulting Student Nonviolent Coordinating Committee initially focused on communication, coordination, and shared strategy. The Student Voice newsletter helped carry information among campus groups. Independence gave young organizers room to make their own decisions while continuing to draw on older activists’ advice, contacts, and material assistance.', 'sncc-founding')),
    s('learning-and-disagreement', 'Experience, debate, and nonviolence', p('Students from Nashville brought experience of disciplined nonviolent protest and training with James Lawson. Diane Nash, John Lewis, and other participants influenced the new organization’s methods. Yet the commitment to nonviolence was discussed and debated rather than accepted in precisely the same way by everyone. Baker helped participants work through disagreements. These exchanges were part of SNCC’s formation: the committee was a setting where activists could compare what had worked, examine principles, and decide how to act together.', 'sncc-founding')),
    s('beyond-the-lunch-counter', 'Local relationships widen the work', p('The organization’s early development also led toward voter organizing. Baker and Jane Stembridge helped Bob Moses travel through the South using contacts built over years of earlier activism. In Mississippi, Amzie Moore urged Moses to direct student energy toward voter registration. That encounter shows the relationship between youthful participation and established local leadership. SNCC’s work grew through conversations with people who knew their communities and the obstacles they faced, extending the struggle beyond the immediate demand for service at a lunch counter.', 'sncc-birth')),
  ], [
    t('February 1960', 'The sit-in wave creates new connections among student activists.', 'sncc-birth'),
    t('April 1960', 'The Shaw University conference establishes a temporary coordinating committee.', 'sncc-founding'),
    t('Summer 1960', 'Moses’s Southern travels connect student organizing with Mississippi voting campaigns.', 'sncc-birth'),
  ], p('The SNCC Digital Gateway combines research with the perspectives of movement veterans. Charlie Cobb’s account identifies its author and his later SNCC service. The sources describe a developing organization, not a claim that all of its later positions were settled at the founding meeting.', 'sncc-birth', 'sncc-founding')),

  'freedom-rides': essay([
    s('testing-existing-rights', 'Testing rights that existed on paper', p('The Freedom Rides challenged the failure to enforce desegregation in interstate transportation. Earlier court decisions had restricted segregation on interstate buses and in facilities used by travelers. On May 4, 1961, an interracial group organized by the Congress of Racial Equality left Washington for the South. Riders used their own journeys to test whether those decisions had practical force. The campaign followed the 1947 Journey of Reconciliation, but entered a new period of student mobilization and direct action.', 'freedom-rides')),
    s('violence-in-alabama', 'White supremacist violence threatens the campaign', p('In Alabama, riders faced violent attacks. A mob firebombed a bus near Anniston on May 14; riders on the other bus were attacked in Birmingham. The violence and the absence of effective protection made further travel extraordinarily dangerous. The original group eventually continued to New Orleans by air. Images and reports of the assaults exposed the gulf between a legal right to travel and what white supremacists, with local officials failing to protect passengers, could still impose.', 'freedom-rides')),
    s('students-continue-the-rides', 'Nashville organizers refuse to let violence decide', p('Nashville students insisted that abandoning the rides would allow violence to determine the movement’s limits. Diane Nash helped coordinate the continuation. Riders returned to Birmingham and then traveled onward despite arrests, delays, and another mob attack in Montgomery. More volunteers joined through the spring and summer, and many were jailed, particularly in Mississippi. The campaign’s continuity depended on that willingness to replace and support endangered participants, making it a story of an expanding network rather than only the first busload.', 'freedom-rides-sncc')),
    s('federal-regulation-and-enforcement', 'Pressure reaches the federal government', p('The rides pushed the Kennedy administration to act. On May 29, Attorney General Robert Kennedy petitioned the Interstate Commerce Commission for regulations against segregation. The resulting rules required integration of interstate bus carriers and terminal facilities by November 1, 1961. Removing segregation signs and enforcing access did not erase all discrimination in travel. It did, however, translate a campaign of repeated journeys into a specific federal regulatory response, demonstrating how direct action could force attention to rights that authorities had failed to secure.', 'freedom-rides-nps')),
  ], [
    t('May 4, 1961', 'The CORE-organized riders leave Washington.', 'freedom-rides'),
    t('May 1961', 'Nashville students continue the campaign after the Alabama attacks.', 'freedom-rides-sncc'),
    t('November 1, 1961', 'The ICC’s integration requirements take effect for interstate bus facilities.', 'freedom-rides-nps'),
  ], p('The sources distinguish the original CORE ride from the larger campaign carried forward by students and later volunteers. The policy victory concerned interstate transportation and facilities under federal jurisdiction; it was not a single order integrating every local business in the South.', 'freedom-rides-nps', 'freedom-rides-sncc')),

  'march-washington': essay([
    s('organizing-a-national-demonstration', 'The organizing behind the crowd', p('The March on Washington for Jobs and Freedom on August 28, 1963, assembled roughly a quarter of a million people. It grew from years of organizing rather than from one speaker’s invitation. A. Philip Randolph provided leadership rooted in the labor movement, while Bayard Rustin directed much of the practical preparation as deputy director. Rustin brought experience in nonviolent protest, earlier Washington demonstrations, and work with Martin Luther King Jr. Coordinating the gathering made that accumulated experience visible on a national stage.', 'march', 'march-rustin')),
    s('jobs-and-freedom', 'Employment was central to the demands', p('The march’s name joined economic security to civil rights. Organizers demanded strong civil rights legislation, protection of voting rights, desegregated public schools, and fair employment protections. They also called for a large federal program to train and employ jobless workers. This agenda connected access to a restaurant or polling place with the ability to earn a living. Treating the event only as a celebration of racial harmony loses the specific demands for government action on work, education, and political power.', 'march-stanford')),
    s('a-coalition-with-disagreements', 'A broad coalition that negotiated its differences', p('Civil rights organizations, religious groups, and unions participated, including the NAACP, Urban League, SCLC, CORE, SNCC, and United Auto Workers. Their cooperation did not eliminate disagreement. John Lewis revised portions of his prepared speech after other leaders objected to its criticism and language. The AFL-CIO’s executive board remained neutral even though member unions participated. These tensions reveal a coalition balancing militant demands, legislative strategy, and a shared demonstration; they should not be edited out of the history of its unity.', 'march-stanford')),
    s('kings-speech-in-context', 'King’s speech within the day’s program', p('King delivered his address near the end of a program of speeches and music. The familiar dream passages drew on themes he had used in earlier sermons and addresses, including his Detroit speech that June. His Washington remarks linked emancipation and constitutional promises to rights still denied, then moved beyond the prepared manuscript. Remembering the speech in that context preserves both its craftsmanship and its urgency. It was a demand addressed to an unfinished political struggle, not an announcement that equality had already arrived.', 'march-speech')),
    s('pressure-and-legislative-aftermath', 'Opposition and legislative aftermath', p('Opposition included attempts to prevent the demonstration itself. Representative Albert Watson proposed suspending mass protests while Congress considered the civil rights bill. Representative William Tuck proposed restricting interstate travel intended to incite rioting, a measure that could have been used against the march. Neither proposal advanced beyond committee. The peaceful gathering took place despite predictions of violence.', 'march'), p('The civil rights bill was already before Congress when marchers arrived. Opponents had tried to restrict demonstrations, and the National Archives notes that the march did not immediately alter the congressional balance of power. The Civil Rights Act became law on July 2, 1964, after further organizing and legislative struggle. Its passage required overcoming obstruction in the House and a Senate filibuster. The march helped sustain public pressure, but the evidence does not make a single day or speech the sole cause of the law.', 'march', 'civil-rights-act')),
  ], [
    t('June 19, 1963', 'Kennedy sends Congress his civil rights message before the march.', 'march'),
    t('August 28, 1963', 'Demonstrators assemble for jobs and freedom; King delivers his address.', 'march'),
    t('July 2, 1964', 'Johnson signs the Civil Rights Act after a contested legislative campaign.', 'civil-rights-act'),
  ], p('Planning records and congressional documents establish demands and political resistance; the King Institute supplies coalition and speech context. Crowd totals remain approximate. The speech is discussed in original prose and linked as evidence; its text and historical photographs are not reproduced.', 'march', 'march-stanford', 'march-speech')),
};

